 using System.ComponentModel;
 using Microsoft.Agents.AI;
 using Microsoft.Extensions.AI;
 using OpenAI;

 // --- Configuration ---
 var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
     ?? throw new InvalidOperationException(
         "Set the OPENAI_API_KEY environment variable before running.");

 const string modelId = "gpt-4o-mini-2024-07-18";

 // --- Build the IChatClient through MEAI ---
 IChatClient chatClient = new OpenAIClient(apiKey)
     .GetChatClient(modelId)
     .AsIChatClient();

 // --- Define the tools the agent can use ---
 var tools = new AITool[]
 {
     AIFunctionFactory.Create(ResearchTools.SearchWeb),
     AIFunctionFactory.Create(ResearchTools.SaveNote),
     AIFunctionFactory.Create(ResearchTools.GetNotes),
 };

 // --- Create the research agent via Microsoft Agent Framework ---
 var agent = new ChatClientAgent(
     chatClient,
     name: "ResearchAgent",
     description: "An AI agent that researches topics by searching the web and taking notes.",
     instructions: """
         You are a research assistant. When given a topic:
         1. Search the web for relevant information using the SearchWeb tool.
            Perform multiple searches with different queries to get broad coverage.
         2. Save important findings as notes using the SaveNote tool.
         3. After gathering enough information, retrieve all notes with GetNotes.
         4. Produce a well-structured summary with:
            - An overview paragraph
            - Key findings as bullet points
            - A brief conclusion
         Be thorough but concise. Cite search queries you used.
         """,
     tools: tools);

 // --- Run the agent ---
 Console.WriteLine("╔══════════════════════════════════════╗");
 Console.WriteLine("║       Research Agent (MAF + MEAI)    ║");
 Console.WriteLine("╚══════════════════════════════════════╝");
 Console.Write("\nEnter a research topic: ");
 var topic = Console.ReadLine();

 if (string.IsNullOrWhiteSpace(topic))
 {
     Console.WriteLine("No topic provided. Exiting.");
     return;
 }

 Console.WriteLine($"\nResearching: {topic}\n");

 var session = await agent.CreateSessionAsync();

 var runOptions = new ChatClientAgentRunOptions(new ChatOptions
 {
     Temperature = 0f,
     MaxOutputTokens = 2048,
 });

 var response = await agent.RunAsync(
     $"Research the following topic and provide a comprehensive summary: {topic}",
     session,
     runOptions);

 Console.WriteLine("\n══════════════ Research Summary ══════════════\n");
 Console.WriteLine(response.Text);
 Console.WriteLine("\n══════════════════════════════════════════════\n");

 // --- Tool implementations ---
 static class ResearchTools
 {
     private static readonly List<string> s_notes = [];
     private static readonly HttpClient s_httpClient = new();

     [Description("Searches the web for information on a query. Returns search result snippets.")]
     public static async Task<string> SearchWeb(
         [Description("The search query to look up")] string query)
     {
         Console.WriteLine($"  🔍 Searching: \"{query}\"");

         try
         {
             // Use DuckDuckGo Instant Answer API (no key required)
             var encoded = Uri.EscapeDataString(query);
             var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
             var json = await s_httpClient.GetStringAsync(url);

             using var doc = System.Text.Json.JsonDocument.Parse(json);
             var root = doc.RootElement;
             var results = new List<string>();

             // Abstract
             var abstractText = root.GetProperty("AbstractText").GetString();
             if (!string.IsNullOrWhiteSpace(abstractText))
             {
                 var source = root.GetProperty("AbstractSource").GetString();
                 results.Add($"[{source}] {abstractText}");
             }

             // Related topics
             if (root.TryGetProperty("RelatedTopics", out var related))
             {
                 foreach (var item in related.EnumerateArray().Take(5))
                 {
                     if (item.TryGetProperty("Text", out var text))
                     {
                         var snippet = text.GetString();
                         if (!string.IsNullOrWhiteSpace(snippet))
                         {
                             results.Add(snippet);
                         }
                     }
                 }
             }

             if (results.Count == 0)
             {
                 return $"No detailed results found for '{query}'. Try a different search query.";
             }

             return string.Join("\n\n", results);
         }
         catch (Exception ex)
         {
             return $"Search failed: {ex.Message}. Try a different query.";
         }
     }

     [Description("Saves a research note for later reference. Use this to record important findings.")]
     public static string SaveNote(
         [Description("The note content to save")] string note)
     {
         s_notes.Add(note);
         Console.WriteLine($"  📝 Note saved ({s_notes.Count} total)");
         return $"Note saved. You now have {s_notes.Count} note(s).";
     }

     [Description("Retrieves all saved research notes.")]
     public static string GetNotes()
     {
         if (s_notes.Count == 0)
         {
             return "No notes saved yet.";
         }

         Console.WriteLine($"  📋 Retrieved {s_notes.Count} note(s)");
         return string.Join("\n---\n",
             s_notes.Select((n, i) => $"Note {i + 1}: {n}"));
     }
 }
